mapper.select:
SELECT al.id, al.admin_id AS adminId, al.action, al.target_type AS targetType, al.target_id AS targetId, al.old_value AS oldValue, al.new_value AS newValue, al.ip, al.create_time AS createTime FROM admin_log al WHERE 1 = 1
AND al.target_type = #{targetType}
AND al.admin_id = #{adminId}
ORDER BY al.create_time DESC
